def signedRayTransport (n : ℕ) (a : (Fin n → ℝ) → ℝ)
    (f : (Fin n → ℝ) → (Fin n → ℝ)) (u : Fin (n + 1) → ℝ) : Fin (n + 1) → ℝ :=
  Fin.cons (u 0 * a (signedTailLinear n u)) (f (signedTailLinear n u))

